bloomstrength.script:
'use strict';

const audio = engine.registerAudioBuffers(engine.AUDIO_RESOLUTION_16);
let smoothGlow = 0.0;

export function update(value) {
	if (!audio || !audio.average) return value;
	let b = (audio.average[0] + audio.average[1]) * 0.5;
	smoothGlow += (b - smoothGlow) * 0.22;
	return 1.0 + smoothGlow * 1.2;
}

scale.script:
'use strict';

const audio = engine.registerAudioBuffers(engine.AUDIO_RESOLUTION_16);
let smoothBass = 0.0;

export function update(value) {
	if (!audio || !audio.average) return value;
	let raw = (audio.average[0] * 1.6 + audio.average[1] * 1.2 + audio.average[2] * 0.7) / 3.5;
	smoothBass += (raw - smoothBass) * 0.25;
	let s = 1.0 + Math.min(0.22, smoothBass * 0.28);
	return new Vec3(s, s, 1.0);
}
